#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=7

# Always work from the project folder, wherever the script was started.
cd "$(dirname "$0")/.."

CHANNEL="preview"
PROJECT_ID=""

# The project a previous run saved, if any.
saved_project() {
  [[ -f .firebaserc ]] || return 0
  sed -n 's/.*"default": *"\([^"]*\)".*/\1/p' .firebaserc | head -n1
}

# The Hosting site exists when the project's own ID shows up in the list of sites.
has_site() {
  local sites
  sites=$(firebase hosting:sites:list --project "$PROJECT_ID" 2>&1 || true)
  [[ "$sites" == *"$PROJECT_ID"* ]]
}

banner "Put the rocket game online with Firebase Hosting"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Check your tools"
if ! command -v node >/dev/null 2>&1; then
  warn "Node.js is missing. Install it from https://nodejs.org and run this again."
  exit 1
fi
printf '  %s✓%s Node %s\n' "$GREEN" "$RESET" "$(node --version)"
if ! command -v firebase >/dev/null 2>&1; then
  warn "The Firebase command-line tool is missing."
  if confirm "Install it now with: npm install -g firebase-tools"; then
    npm install -g firebase-tools
  else
    say "Install it, then run this again."
    exit 1
  fi
fi
printf '  %s✓%s Firebase tool %s\n' "$GREEN" "$RESET" "$(firebase --version)"
if [[ ! -d node_modules ]]; then
  say "Installing the game's packages..."
  npm ci
fi
printf '  %s✓%s Game packages installed\n' "$GREEN" "$RESET"
pause "Press Enter to continue"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Log in to Firebase"
say "A browser window opens for you to sign in, unless you're already logged in."
step "Choose the Google account that should own this game."
step "Allow the Firebase command-line tool when Google asks."
firebase login
printf '\n'
say "Logged in accounts:"
firebase login:list
pause "Press Enter if that's the right account (Ctrl-C to stop)"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Create the Firebase project"
SAVED=$(saved_project)
if [[ -n "$SAVED" ]] && confirm "Use the project saved earlier, $SAVED?"; then
  PROJECT_ID="$SAVED"
else
  open_url "https://console.firebase.google.com/"
  step "Create a new project (the button may say Create a project or Add project)."
  step "Give it a name, like Rocket Lab."
  step "Under the name, note the Project ID. It becomes part of your web address."
  step "Turn Google Analytics off when asked, and leave any other extras off."
  step "Wait until the console says the project is ready."
  printf '\n'
  while true; do
    ask PROJECT_ID "Paste the Project ID:"
    if [[ ! "$PROJECT_ID" =~ ^[a-z][a-z0-9-]{4,28}[a-z0-9]$ ]]; then
      warn "A Project ID is 6 to 30 lowercase letters, digits and dashes. Try again."
      continue
    fi
    PROJECTS=$(firebase projects:list 2>&1 || true)
    if [[ "$PROJECTS" == *"$PROJECT_ID"* ]]; then
      break
    fi
    warn "This account can't see a project called $PROJECT_ID. Check the ID and try again."
  done
fi
printf '{\n  "projects": {\n    "default": "%s"\n  }\n}\n' "$PROJECT_ID" > .firebaserc
printf '  %s✓ saved%s %s → .firebaserc\n' "$GREEN" "$RESET" "$PROJECT_ID"
pause "Press Enter to continue"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Turn on Hosting"
while ! has_site; do
  open_url "https://console.firebase.google.com/project/$PROJECT_ID/hosting"
  step "If the page shows a Get started button, click it and go through the steps."
  note "Skip any commands it lists; this wizard runs those for you."
  pause "Press Enter once the Hosting page has finished setting up"
done
printf '  %s✓%s Hosting is ready for %s\n' "$GREEN" "$RESET" "$PROJECT_ID"
pause "Press Enter to continue"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Write the Firebase config"
say "This creates firebase.json, which tells Firebase to publish the dist folder,"
say "and keeps Firebase's own cache folder out of git."
if [[ -f firebase.json ]]; then
  warn "firebase.json already exists:"
  sed 's/^/    /' firebase.json
fi
if ! confirm "Write firebase.json now?"; then
  say "Stopped. Nothing was published."
  exit 0
fi
cat > firebase.json <<'JSON'
{
  "hosting": {
    "public": "dist",
    "ignore": ["firebase.json", "**/.*", "**/node_modules/**"]
  }
}
JSON
printf '  %s✓ wrote%s firebase.json\n' "$GREEN" "$RESET"
if ! grep -qxF '.firebase/' .gitignore 2>/dev/null; then
  printf '.firebase/\n' >> .gitignore
  printf '  %s✓ added%s .firebase/ → .gitignore\n' "$GREEN" "$RESET"
fi
pause "Press Enter to continue"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Try a private test link"
say "Building the game from what's in this folder right now..."
npm run build
printf '\n'
say "Uploading to a temporary link that expires in 7 days..."
DEPLOY_LOG=$(mktemp)
firebase hosting:channel:deploy "$CHANNEL" --expires 7d --project "$PROJECT_ID" 2>&1 | tee "$DEPLOY_LOG"
# Firebase prints the live "Hosting URL" as well; only the channel's own address has the game on it yet.
PREVIEW_URL=$(grep -Eo "https://[^ ]+--${CHANNEL}-[^ ]+\.web\.app" "$DEPLOY_LOG" | head -n1 || true)
rm -f "$DEPLOY_LOG"
printf '\n'
if [[ -n "$PREVIEW_URL" ]]; then
  open_url "$PREVIEW_URL"
else
  warn "Couldn't find the test link automatically. Open the Channel URL printed above."
fi
step "Check the menu appears and OPTIONS opens."
step "Start FLIGHT SCHOOL > GAME GUIDE and confirm you hear the radio voice."
step "Build and launch a rocket, then finish or crash to hear the end call."
pause "Press Enter when you've finished testing"
if ! confirm "Did everything work?"; then
  say "Stopped before going live. Fix the problem and run this again."
  exit 0
fi

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Go live"
say "This publishes the game for anyone with the link:"
say "  https://$PROJECT_ID.web.app"
printf '\n'
warn "The radio voice was recorded with a macOS voice. Apple's licence allows those"
warn "for personal, non-commercial use. Replace it first if that doesn't fit."
printf '\n'
if confirm "Publish the game now?"; then
  firebase deploy --only hosting --project "$PROJECT_ID"
  printf '\n'
  open_url "https://$PROJECT_ID.web.app"
  pause "Press Enter once the live game has opened"
else
  SKIPPED+=("Go live: firebase deploy --only hosting --project $PROJECT_ID")
fi

finish
say "Live address:     https://$PROJECT_ID.web.app"
say "Publish changes:  npm run build, then firebase deploy --only hosting"
say "Take it offline:  firebase hosting:disable --project $PROJECT_ID"
printf '\n'
